from __future__ import annotations

import asyncio
from typing import Any

import pytest

import llm_router
import tests.llm_router.support.builders as builders

pytestmark = pytest.mark.verification_kind("unit")


def _create_router(**kwargs: Any) -> Any:
    for name in ("build_router", "make_router", "build_test_router"):
        fn = getattr(builders, name, None)
        if callable(fn):
            try:
                return fn(**kwargs)
            except Exception:
                pass
            try:
                return fn()
            except Exception:
                pass
            for candidate in ("test-route", "mock", "test", "openai/gpt-4o"):
                try:
                    return fn(candidate, **kwargs)
                except Exception:
                    pass
                try:
                    return fn(spec=candidate, **kwargs)
                except Exception:
                    pass

    if hasattr(builders, "RouterBuilder"):
        cls = getattr(builders, "RouterBuilder")
        builder = cls()
        if hasattr(builder, "build"):
            return builder.build()

    if hasattr(llm_router, "LLMRouter"):
        return llm_router.LLMRouter(**kwargs)

    raise RuntimeError("Unable to construct router using builders or llm_router")


def _extract_attempts(response: Any) -> list[Any]:
    trace = getattr(response, "trace", None)
    if trace is not None and hasattr(trace, "attempts"):
        return list(trace.attempts)
    if hasattr(response, "attempts"):
        return list(response.attempts)
    if isinstance(trace, (list, tuple)):
        return list(trace)
    traces = getattr(response, "traces", None)
    final_trace = getattr(response, "final_trace", None)
    if traces is not None and final_trace is not None:
        return [*list(traces), final_trace]
    if traces is not None and isinstance(traces, (list, tuple)):
        return list(traces)
    if trace is not None:
        return [trace]
    return []


@pytest.mark.verifies("REQ_ASYNC_PROVIDER_EXECUTION[revision==1]")
def test_async_provider_execution_non_rate_limited_route() -> None:
    async def _run() -> None:
        sync_router = _create_router()
        async_router = _create_router()

        content = "Hello, normalized text request verification."
        sync_response = sync_router.query(content)

        runtime = getattr(async_router, "_runtime", async_router)
        blocked_async_called = False
        orig_run_blocked_async = getattr(runtime, "_run_blocked_async", None)

        if callable(orig_run_blocked_async):
            async def spy_run_blocked_async(*args: Any, **kwargs: Any) -> Any:
                nonlocal blocked_async_called
                blocked_async_called = True
                return await orig_run_blocked_async(*args, **kwargs)

            runtime._run_blocked_async = spy_run_blocked_async

        try:
            async_response = await async_router.aquery(content)
        finally:
            if callable(orig_run_blocked_async):
                runtime._run_blocked_async = orig_run_blocked_async

        assert not blocked_async_called, (
            "Expected direct provider execution without entering blocked routing"
        )

        sync_attempts = _extract_attempts(sync_response)
        async_attempts = _extract_attempts(async_response)

        assert len(async_attempts) == 1, (
            f"Expected exactly 1 attempt in async trace, got {len(async_attempts)}"
        )
        assert len(sync_attempts) == 1, (
            f"Expected exactly 1 attempt in sync trace, got {len(sync_attempts)}"
        )
        assert len(async_attempts) == len(sync_attempts)

        async_attempt = async_attempts[0]
        sync_attempt = sync_attempts[0]

        assert getattr(async_attempt, "blocked", False) is False
        assert getattr(sync_attempt, "blocked", False) is False
        assert getattr(async_attempt, "wait_seconds", 0) in (0, 0.0, None)
        assert getattr(sync_attempt, "wait_seconds", 0) in (0, 0.0, None)
        assert getattr(async_attempt, "error", None) is None
        assert getattr(sync_attempt, "error", None) is None

        status = getattr(async_attempt, "status", None)
        if status is not None:
            assert status not in ("blocked", "rate_limited", "failed", "error")

        async_traces = getattr(async_response, "traces", None)
        sync_traces = getattr(sync_response, "traces", None)
        if async_traces is not None:
            assert len(async_traces) == 0, (
                f"Expected 0 blocked/failed traces, got: {async_traces}"
            )
        if sync_traces is not None:
            assert len(sync_traces) == 0

        if hasattr(async_response, "fallback_occurred"):
            assert async_response.fallback_occurred is False

    asyncio.run(_run())
